/**
 * Les noms d'usage de l'application, vers leur dessin Phosphor.
 *
 * Garder ces noms évite de renommer 60 appels pour un changement de jeu, et
 * garde le vocabulaire métier : `private` dit l'intention, `eye-slash` dit le
 * dessin.
 */
const ALIASES = {
  back: "arrow-left",
  calendar: "calendar-blank",
  chart: "chart-line",
  chat: "chat-circle",
  chevron: "caret-right",
  close: "x",
  download: "download-simple",
  edit: "pencil-simple",
  extensions: "plugs",
  figures: "users-three",
  forward: "arrow-right",
  marketplace: "storefront",
  memory: "brain",
  menu: "sidebar-simple",
  mic: "microphone",
  models: "cube",
  more: "dots-three",
  music: "music-notes",
  private: "eye-slash",
  project: "folder-simple",
  refresh: "arrow-clockwise",
  search: "magnifying-glass",
  server: "hard-drives",
  settings: "gear",
  shield: "shield-check",
  sound: "speaker-high",
  speed: "gauge",
  studio: "sparkle",
  target: "crosshair",
  video: "video-camera",
};
/** Tous les noms acceptés : les dessins Phosphor et les alias de l'application. */
export const ICON_NAMES: readonly string[] = [
  ...Object.keys(PATHS),
  ...Object.keys(ALIASES),
].sort();

/** L'union réelle des noms acceptés : un nom fautif ne compile pas. */
export type IconName = keyof typeof PATHS | keyof typeof ALIASES;

/**
 * Vrai si `name` désigne une icône du jeu.
 *
 * Une extension nomme une icône dans son manifeste ; l'application la dessine.
 * Un nom inconnu n'est pas une icône, et vaut alors une icône de secours côté
 * appelant plutôt qu'un rendu vide.
 */
export function isIconName(name: string | null | undefined): name is IconName {
  if (!name) return false;
  return name in PATHS || name in ALIASES;
}

type Props = {
  name: IconName;
  /** Taille en pixels ; carré. 16 en ligne, 20 en navigation, 24 pour un en-tête. */
  size?: number;
  /** Titre accessible. Absent : l'icône est décorative et reste muette. */
  title?: string;
};

/** Le tracé d'un nom, qu'il soit un dessin Phosphor ou un alias de l'application. */
function pathFor(name: IconName): string | undefined {
  const drawing = name in ALIASES ? ALIASES[name as keyof typeof ALIASES] : name;
  return PATHS[drawing as keyof typeof PATHS];
}

export function Icon({ name, size = 20, title }: Props) {
  const d = pathFor(name);
  // Un nom inconnu ne dessine rien plutôt qu'un carré de secours : la place
  // reste tenue, et l'appelant garde la main sur ce qu'il montre à la place.
  if (!d) return null;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 256 256"
      fill="currentColor"
      // Une icône sans titre accompagne toujours un mot : la lire à voix haute
      // ne ferait que répéter.
      aria-hidden={title ? undefined : true}
      role={title ? "img" : undefined}
      focusable={false}
    >
      {title ? <title>{title}</title> : null}
      <path d={d} />
    </svg>
  );
}
